sketch:
// Servo — turning a horn without a Timer surgery story.
//
// The bundled Servo library puts a 544-2400 microsecond pulse on pin 9,
// once every 20 ms. write() speaks in degrees: the horn swings 0 to 180
// and back, twenty steps a second.

#include <Servo.h>

Servo horn;

void setup() {
  horn.attach(9);
}

void loop() {
  for (int angle = 0; angle <= 180; angle += 20) {
    horn.write(angle);
    delay(200);
  }
  for (int angle = 180; angle >= 0; angle -= 20) {
    horn.write(angle);
    delay(200);
  }
}
